package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;import org.junit.Test;import static org.junit.Assert.*;
public class PropositionRelationsTest {
 private List<Long> values(Question q){List<Long> n=new ArrayList<>();Matcher m=Pattern.compile("[0-9]+").matcher(q.prompt);while(m.find())n.add(Long.parseLong(m.group()));assertEquals(2,n.size());long v=n.get(0),d=n.get(1),quot=v/d,product=d*quot,rem=v-product;List<Long> result=new ArrayList<>(List.of(v,d,quot,product,rem));if(q.skillId.equals("sec_contrapositive")){boolean implication=true;for(int x=-200;x<=200;x++)if(x%v==0&&x%d!=0)implication=false;assertEquals(rem==0,implication);result.add(1L);}result.add(rem==0?1L:0L);return result;}
 private void verify(Question q){List<Long> v=values(q);assertTrue(new Checker().check(q,List.of(),List.of(v.get(v.size()-1).toString())).correct());String id=q.id,prompt=q.prompt,signature=q.signature();Arrays.fill(q.answers,"9999");q.givenNumbers.replaceAll((k,x)->"9999");q.choiceInputs=new Rational[]{Rational.of(9999)};HelpPlan p=HelpPlan.forQuestion(q);assertEquals(v.size(),p.size());assertFalse(p.canTransfer());assertEquals(id,q.id);assertEquals(prompt,q.prompt);assertEquals(signature,q.signature());for(int i=0;i<v.size();i++){var step=p.step(i);assertTrue(step.accepts(v.get(i).toString()));assertFalse(step.accepts(Long.toString(step.options.isEmpty()?v.get(i)+1:1-v.get(i))));assertEquals("",step.after);assertFalse(step.before.matches(".*[0-9].*"));}}
 @Test public void publicDivisionSuppliesAllDistinctSmallPromptsAndVariedRemainders(){Generator g=new Generator(new Random(2701));for(String skill:List.of("sec_proposition_truth","sec_contrapositive")){Set<String> prompts=new HashSet<>();Set<Integer> positions=new HashSet<>();Set<Long> remainders=new HashSet<>();for(int i=0;i<16000;i++){Question q=g.next(skill,List.of(),i%2==0);prompts.add(q.prompt);positions.add(q.correctChoice);remainders.add(values(q).get(4));verify(q);}assertEquals(skill.equals("sec_proposition_truth")?396:352,prompts.size());assertEquals(Set.of(0,1),positions);assertEquals(Set.of(0L,1L,2L,3L,4L,5L,6L,7L,8L),remainders);}}
 @Test public void savedQuestionsAndZeroQuotientKeepIdentityAndReplaceOldHelpDraft(){for(Question q:List.of(new Question("sec_proposition_truth","명제 ‘0은 3의 배수이다’의 참과 거짓을 고르세요.","","1"),new Question("sec_proposition_truth","명제 ‘2은 5의 배수이다’의 참과 거짓을 고르세요.","","0"),new Question("sec_contrapositive","명제 ‘n이 12의 배수이면 n은 3의 배수이다’의 대우가 참인지 거짓인지 고르세요.","","1"),new Question("sec_contrapositive","명제 ‘n이 13의 배수이면 n은 3의 배수이다’의 대우가 참인지 거짓인지 고르세요.","","0"),new Question("sec_contrapositive","정수 n에 대한 명제 ‘n이 2의 배수이면 n은 5의 배수이다’의 대우가 참인지 거짓인지 고르세요.","","0"))){q.studyGuide=new StudyGuide().step("옛 도움","13 ÷ 3 = ","","1");verify(q);HelpPlan p=HelpPlan.forQuestion(q);HelpPlan.Draft draft=new HelpPlan.Draft();draft.questionId=q.id;draft.stage=1;draft.entries=new ArrayList<>(List.of("1"));p.restore(draft,q.id);assertEquals(0,draft.stage);assertEquals("",draft.entries.get(0));draft.entries.set(0,values(q).get(0).toString());draft.stage=1;assertEquals(1,HelpPlan.forQuestion(q).restore(draft.copy(),q.id).stage);}}
}
